const crypto = require('crypto');

// Paste your MercadoPago webhook secret here
// (Your integrations > Webhooks > Configure notifications > Secret key).
// While it is the placeholder, every notification is rejected.
const SECRET = 'YOUR_MERCADOPAGO_WEBHOOK_SECRET';

const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};
const query = item.json.query || {};

// x-signature arrives as "ts=...,v1=...".
const parts = {};
for (const part of String(headers['x-signature'] || '').split(',')) {
  const [key, value] = part.split('=');
  if (key && value) parts[key.trim()] = value.trim();
}
const ts = parts.ts || '';
const v1 = parts.v1 || '';
const requestId = String(headers['x-request-id'] || '');

// data.id comes in the query string (?data.id=) or in the body.
// Payment ids are numeric. Nothing else goes into the API path.
const dataId = String(query['data.id'] || (body.data && body.data.id) || '');

let signatureValid = false;
if (SECRET !== 'YOUR_MERCADOPAGO_WEBHOOK_SECRET' && ts && v1 && /^[0-9]+$/.test(dataId)) {
  // MercadoPago leaves out of the signed manifest any part the notification lacks.
  const manifest = `id:${dataId};` + (requestId ? `request-id:${requestId};` : '') + `ts:${ts};`;
  const expected = Buffer.from(crypto.createHmac('sha256', SECRET).update(manifest).digest('hex'));
  const received = Buffer.from(v1);
  // Constant-time comparison. timingSafeEqual throws on different byte lengths.
  signatureValid = expected.length === received.length && crypto.timingSafeEqual(expected, received);
}

return [{ json: { paymentId: dataId, signatureValid } }];

